CREATE SET TABLE MDP01_META.META_ETL_SCHEDULE ,FALLBACK ,     NO BEFORE JOURNAL,     NO AFTER JOURNAL,     CHECKSUM = DEFAULT,     DEFAULT MERGEBLOCKRATIO,     MAP = TD_MAP1     (      schedule_id INTEGER NOT NULL,      etl_job_id INTEGER NOT NULL,      schedule_type VARCHAR(50) CHARACTER SET LATIN NOT CASESPECIFIC NOT NULL,      cron_expression VARCHAR(100) CHARACTER SET LATIN NOT CASESPECIFIC,      interval_minutes INTEGER,      trigger_event VARCHAR(100) CHARACTER SET LATIN NOT CASESPECIFIC,      earliest_start_time TIME(6),      latest_start_time TIME(6),      is_active CHAR(1) CHARACTER SET LATIN NOT CASESPECIFIC DEFAULT 'Y',      next_run_time TIMESTAMP(6),      max_retries INTEGER DEFAULT 3 ,      retry_delay_minutes INTEGER DEFAULT 5 ,      ersterfassungsdatum TIMESTAMP(6) NOT NULL,      aenderungsdatum TIMESTAMP(6) NOT NULL)PRIMARY INDEX ( schedule_id )INDEX ( etl_job_id );